            s1t: "Core seller rules",
            s1p1: "Sellers should list only products they can honestly supply, use clear images, keep prices current, and explain condition, delivery, and pickup details before the buyer pays. A product listing is a promise to the buyer, not just a marketing post.",
            s1p2: "A seller should not impersonate another business, make false verification claims, hide major defects, or accept payment for items they know are unavailable. These actions weaken trust across the marketplace.",
            s2t: "Dispute expectations",
            s2p1: "If a dispute happens, sellers should provide order details, product evidence, message history, delivery proof, and a clear explanation. Good records help support understand the situation quickly.",
            s2p2: "UrMall should protect honest sellers and buyers, but it cannot do that well when transactions are unclear. Keep conversations organized and connected to the product or order whenever possible.",
