          heroTitle: "Tout ce dont les vendeurs sérieux ont besoin dans un seul espace",
          heroBody: "Gérez la confiance, les produits, les commandes, les messages, la livraison, la croissance, les performances, les signalements, la sécurité et les politiques depuis un espace de travail UrMall clair.",
