            s1p2: "Un vendeur ne doit pas usurper l'identité d'une autre entreprise, faire de fausses déclarations de vérification, cacher des défauts majeurs ni accepter un paiement pour des articles qu'il sait indisponibles. Ces actions affaiblissent la confiance dans toute la marketplace.",
