          policy: {
            summary: "El centro de políticas del vendedor mantiene UrMall profesional al dejar las reglas claras antes de que surja un problema.",
            h1t: "Productos reales",
            h1x: "Los listados deben ser veraces, estar disponibles y estar claramente descritos.",
            h2t: "Pagos seguros",
            h2x: "Los vendedores no deben confundir a los compradores con instrucciones de pago cambiantes o engañosas.",
            h3t: "Disputas justas",
            h3x: "Los problemas con los pedidos deben manejarse con pruebas, respeto y una comunicación clara.",
            s1t: "Reglas principales del vendedor",
            s1p1: "Los vendedores deben enumerar sólo productos que puedan suministrar honestamente, utilizar imágenes claras, mantener los precios actualizados y explicar el estado, los detalles de entrega y recogida antes de que el comprador pague. Una lista de productos es una promesa para el comprador, no solo una publicación de marketing.",
            s1p2: "Un vendedor no debe hacerse pasar por otra empresa, realizar afirmaciones de verificación falsas, ocultar defectos importantes ni aceptar pagos por artículos que sabe que no están disponibles. Estas acciones debilitan la confianza en todo el mercado.",
            s2t: "Expectativas de disputa",
            s2p1: "Si surge una disputa, los vendedores deben proporcionar los detalles del pedido, evidencia del producto, historial de mensajes, comprobante de entrega y una explicación clara. Los buenos registros ayudan a comprender la situación rápidamente.",
            s2p2: "UrMall debería proteger a los vendedores y compradores honestos, pero no puede hacerlo tan bien cuando las transacciones no son claras. Mantenga las conversaciones organizadas y conectadas con el producto o pedido siempre que sea posible."
          }
