        returnsSummary: "退货和争议应通过订单上下文处理，以便卖家、产品、价格、送货地址和对话历史记录保持联系。",
        returnsS1Title: "从订单开始",
        returnsS1P1: "如果产品到达时已损坏、与列表不同、延迟、丢失或未交付，请从相关订单或买卖双方消息开始。这为支持人员和卖家提供了了解所发生情况所需的信息。",
        returnsS1P2: "强烈争议包括产品名称、订单日期、卖家名称、商定价格、交货详细信息、有用的照片，以及对您的预期与实际情况的清晰解释。",
        returnsS2Title: "升级之前先明确",
        returnsS2P1: "当买家冷静地解释问题并给卖家公平的回应机会时，许多问题都可以很快得到解决。如果卖家没有回应或者问题涉及欺诈、不安全行为或严重失实陈述，则应将问题升级并提供证据。",
        returnsS2P2: "UrMall 正在被塑造为一个值得信赖的市场，因此退货和争议工具应该保护诚实的买家，而不是不公平地惩罚诚实的卖家。",
        supportSummary: "买家支持可帮助您放心购物、清楚了解卖家并解决问题，而不会丢失证明所发生情况的订单历史记录。",
        supportS1Title: "哪里可以获得帮助",
        supportS1P1: "对于产品问题、交货安排、可用性和价格确认，请通过产品或订单向卖家发送消息。产品链接消息比随机聊天更好，因为它们保留了项目上下文。",
        supportS1P2: "对于帐户、安全、可疑卖家行为、虚假付款请求或重复订单问题，请在票证系统激活时使用 UrMall 支持。在此之前，保留证据并使用最相关的卖家消息或订单记录。",
        supportS2Title: "如何撰写有用的支持请求",
        supportS2P1: "专业的支持请求应说明产品、卖家、订购日期、付款预期、送货地址和确切的问题。像“卖家问题”或“我的订单有问题”这样的短消息会导致支持速度变慢，因为缺少重要的事实。",
        supportS2P2: "清晰的支持沟通可以保护您。它还有助于 UrMall 识别虚假市场行为并保护认真的卖家免受虚假投诉。",
        settingsSummary: "买家设置可帮助您保持 UrMall 购物活动井井有条、私密并准备好结帐。",
        settingsS1Title: "您的买家菜单控制什么",
        settingsS1P1: "您的买家菜单将订购的商品、已保存的产品、最近查看的产品、送货地址、临时付款说明、支持指南和争议指南集中在一处。这使得 UrMall 感觉像是一个合适的购买工作区，而不是分散的屏幕。",
        settingsS1P2: "保存的地址使订购速度更快，特别是当您使用不同的送货地点（例如家庭、办公室、市场、学校或其他自定义地点）时。",
        settingsS2Title: "隐私和准确性",
        settingsS2P1: "下订单前，请确保您的电话号码、收件人姓名和送货单准确无误。错误的送货信息可能会耽误卖家的时间，让骑手感到困惑，并引发本来可以避免的纠纷。",
        settingsS2P2: "位置坐标和地址详细信息应仅支持送货和订单处理。它们不应被视为公共档案信息。"
